/* Artist-selected demo journals. No account, publishing or social state. */
const artistStories = {
  'Morrow': ['Piano, tape and the spaces between.', 'Small sounds, held a little longer. Morrow builds a world out of quiet keys, room tone and the light at the end of the day.', 'Leave the window open', 'Sometimes the room has something to say. Leave a little air around the piano. Keep the creak of the chair.', 'studio'],
  'Form & Field': ['A different way through.', 'Repetition, architecture and the softer side of electronic music. A place for sketches that become sounds, and sounds that become shapes.', 'Nothing quite lines up', 'Draw the rhythm before you play it. Straight lines are only the beginning.', 'sketchbook'],
  'Low Tide': ['Transmissions from the water’s edge.', 'Warm low frequencies and coastal nights. Low Tide collects small observations from the places where the city gives way to the sea.', 'The long way home', 'Walk until the traffic falls away. There is a rhythm in the water that never quite repeats.', 'studio'],
  'Vela Saint': ['For the hours that belong to you.', 'Slow grooves, velvet textures and rooms lit by a single lamp. A little intimacy, with room for silence.', 'After everyone leaves', 'The best part of the night is sometimes the quiet afterwards. One lamp. One idea worth keeping.', 'backstage'],
  'Iris Vale': ['Soft edges. A clear voice.', 'A world of close textures, unfinished pages and warm colour. Iris Vale finds little moments worth holding on to.', 'Keep the first version', 'Before it becomes polished, an idea has a particular kind of honesty. Keep a little of that.', 'sketchbook'],
  'Static Harbour': ['Rough edges, open doors.', 'Guitar-led sketches and concrete spaces. Static Harbour makes room for the beautiful things that do not quite behave.', 'Before the doors open', 'A cable on the floor. An amp warming up. That small pause before the room becomes something else.', 'backstage'],
  'Paper Weather': ['Music for the spaces that remain.', 'Empty rooms, guitar textures and fragments of everyday life. A journal of what is left behind and what comes next.', 'A room remembers', 'Move the furniture and the song feels different. Some spaces keep their own kind of echo.', 'studio'],
  'June Assembly': ['Take the afternoon slowly.', 'Loose rhythms, warm light and unhurried listening. June Assembly gathers small details into something you can settle into.', 'No rush to finish', 'Let the afternoon into the room. The next idea can wait until this one has somewhere to land.', 'studio'],
  'Index Field': ['Patterns with a pulse.', 'Cut paper, measured repetition and unexpected colour. Index Field moves between the visual and the musical, following the same thread.', 'One small interruption', 'Repeat a shape until the exception becomes the thing you notice. That is where the next track starts.', 'sketchbook'],
  'Kiki Static': ['A little too much. Just enough.', 'Bright fragments, restless electronics and a fondness for happy accidents. Step into Kiki’s world of colour, distortion and things in progress.', 'Keep the strange bit', 'The sound that should not work. The colour that almost clashes. Usually, that is the part worth keeping.', 'sketchbook'],
  'June Arcade': ['Songs with the windows open.', 'Sun-faded rooms, loose threads and melodies carried home on the last train. Small observations from an imagined indie life.', 'Before the first take', 'The kettle clicks off. Sunlight moves across the floor. A melody arrives before anyone presses record.', 'studio'],
  'Moth Season': ['Somewhere between light and shadow.', 'Alternative textures, half-lit rooms and images that linger. A collection of fragments from the edges of a record.', 'The things just out of frame', 'A reflection in the window. The colour left after sunset. Start with the thing you nearly missed.', 'sketchbook'],
  'The Hollow Youth': ['Turn it up. Stay a while.', 'Scuffed guitars, rehearsal-room energy and the moments around the music. The songs are only one part of the story.', 'Five minutes to soundcheck', 'Nothing glamorous. Just cables, a guitar and the feeling that tonight could become a good memory.', 'backstage'],
  'Sable Noa': ['Warmth in the blue hours.', 'Slow-burning textures and a quiet attention to detail. Sable Noa’s world lives in the space between a late night and a fresh start.', 'One more take', 'Turn the lights down and let the room settle. The smallest change can make everything feel closer.', 'studio']
};
const journalScenes = {
  studio: {src:'assets/artist-world-studio.png', alt:'An imagined home studio with a piano, tape recorder and warm window light.', title:'A room for the next idea', caption:'A fictional studio study: instruments within reach, a notebook open, time to try something.'},
  backstage: {src:'assets/artist-world-backstage.png', alt:'An imagined venue wing with a guitar, amplifier and faded red curtain.', title:'Just before the noise', caption:'An imagined backstage moment. The room is still empty, the cables are down, and the night has not started yet.'},
  sketchbook: {src:'assets/artist-world-sketchbook.png', alt:'An imagined artwork desk with coloured paper, charcoal sketches and a contact sheet.', title:'Still taking shape', caption:'An imagined worktable, collecting colours and textures before they become a finished sleeve.'}
};
function artistSlug(name){return name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function artistForRecord(r){return artistSlug(r.artist)}
function allArtists(){
  return [...new Set(records.map(r=>r.artist))].map(name=>{
    const releases=records.filter(r=>r.artist===name),r=releases[0];
    const [line,bio,noteTitle,note,sceneKey]=artistStories[name]||[r.description,r.description,'From the notebook',r.description,'sketchbook'];
    const scene=journalScenes[sceneKey];
    return {id:artistSlug(name),name,line,bio,releases,genre:r.genre,art:asset(r),featured:releases.some(x=>x.featured),items:[
      {id:'room',category:'BTS',type:'image',...scene},
      {id:'notebook',category:'Notes',type:'note',title:noteTitle,body:note},
      {id:'sleeve',category:'Artwork',type:'image',src:asset(r),alt:r.artAlt||`${r.title} cover artwork`,title:r.title,caption:`The visual world of ${r.title}. A fictional release by ${name}.`,recordId:r.id},
      {id:'moment',category:'Moments',type:'note',title:'A moment to keep',body:line+' A small reminder of what this record is reaching for.'}
    ]};
  }).sort((a,b)=>Number(b.featured)-Number(a.featured)||a.name.localeCompare(b.name));
}
function escapeArtist(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let artistQuery='',artistGenre='All',worldCategory='All',lastArtistId=null;
function artistTile(a,compact=false){return `<a class="artist-tile ${compact?'compact':''}" href="#artist/${a.id}"><div class="artist-tile-image"><img src="${a.art}" alt="${escapeArtist(a.name)}: ${escapeArtist(a.genre)} visual identity" loading="lazy" width="768" height="768"><span class="artist-tile-arrow" aria-hidden="true">↗</span></div><div class="artist-tile-meta"><span>${escapeArtist(a.genre)}</span><h3>${escapeArtist(a.name)}</h3>${compact?'':`<p>${escapeArtist(a.line)}</p>`}</div></a>`}
function artistRail(artists,label){return `<div class="artist-rail" tabindex="0" role="region" aria-label="${label}. Scroll horizontally to browse.">${artists.map(a=>artistTile(a,true)).join('')}</div>`}
function artistDirectoryResults(){
 const list=allArtists().filter(a=>(artistGenre==='All'||a.genre===artistGenre)&&`${a.name} ${a.genre} ${a.line}`.toLowerCase().includes(artistQuery.toLowerCase()));
 return `<p class="artist-result-count" role="status">${list.length} ${list.length===1?'artist':'artists'}</p>${list.length?`<div class="artist-directory-grid">${list.map(a=>artistTile(a)).join('')}</div>`:'<div class="empty"><h2>No artists found.</h2><p>Try another name or genre.</p><button class="secondary" data-action="clear-artists">Show all artists</button></div>'}`;
}
function artistsView(){return `<div class="section-head artist-directory-heading"><div><p class="eyebrow red">THE PEOPLE BEHIND THE RECORDS</p><h1>Find your next favourite.</h1><p class="artist-intro">Come for a record. Stay for their world.</p></div></div><section class="artist-browse-section" aria-label="Artists to explore"><div class="artist-section-heading"><h2>Step into their world</h2><span class="muted">Browse the artists <span aria-hidden="true">↔</span></span></div>${artistRail(allArtists().filter(a=>a.featured),'Artist highlights')}</section><section aria-labelledby="all-artists-heading"><div class="artist-section-heading"><h2 id="all-artists-heading">All artists</h2><label class="search"><span aria-hidden="true">⌕</span><input id="artist-search" type="search" placeholder="Find an artist" aria-label="Find an artist" value="${escapeArtist(artistQuery)}"></label></div><div class="filters artist-filters" role="group" aria-label="Filter artists by genre">${['All',...new Set(allArtists().map(a=>a.genre))].map(g=>`<button class="filter ${artistGenre===g?'active':''}" data-action="artist-genre" data-genre="${escapeArtist(g)}" aria-pressed="${artistGenre===g}">${escapeArtist(g)}</button>`).join('')}</div><div id="artist-results">${artistDirectoryResults()}</div></section><p class="legal-note">Fictional artist profiles and journal material, created for this listening room.</p>`}
function worldGrid(a){
 const items=a.items.filter(x=>worldCategory==='All'||x.category===worldCategory);
 return `<div class="world-grid">${items.map(item=>`<button class="world-tile world-kind-${item.type}" data-action="world-open" data-artist="${a.id}" data-item="${item.id}" aria-label="Open ${escapeArtist(item.title)}, ${item.category}">${item.type==='image'?`<div class="world-image"><img src="${item.src}" alt="${escapeArtist(item.alt)}" loading="lazy" width="1024" height="1024"><span class="world-expand" aria-hidden="true">↗</span></div>`:`<div class="world-note"><span class="eyebrow">${item.category==='Notes'?'FROM THE NOTEBOOK':'A SMALL OBSERVATION'}</span><p>${escapeArtist(item.body)}</p><span class="world-signature">${escapeArtist(a.name)}</span></div>`}<span class="world-caption"><span>${item.category}</span><strong>${escapeArtist(item.title)}</strong></span></button>`).join('')}</div>`;
}
function artistProfile(id){
 const a=allArtists().find(a=>a.id===id);
 if(!a)return '<div class="empty"><h1>Artist not found.</h1><p>There is more to discover in the listening room.</p><a class="primary" href="#artists">Browse artists</a></div>';
 if(lastArtistId!==id){worldCategory='All';lastArtistId=id}
 return `<div class="detail-top"><a class="back" href="#artists">← All artists</a><span class="eyebrow">ARTIST / ${escapeArtist(a.genre.toUpperCase())}</span></div><section class="artist-profile-hero"><div class="artist-portrait"><img src="${a.art}" alt="${escapeArtist(a.name)} visual identity" width="768" height="768"><span>THE WORLD OF / ${escapeArtist(a.name.toUpperCase())}</span></div><div class="artist-profile-copy"><p class="eyebrow red">${escapeArtist(a.genre.toUpperCase())}</p><h1>${escapeArtist(a.name)}</h1><p class="artist-manifesto">${escapeArtist(a.line)}</p><p class="artist-biography">${escapeArtist(a.bio)}</p><div class="actions"><button class="primary" data-action="artist-play" data-id="${a.releases[0].id}">${playIcon} Play the music</button><button class="secondary" data-action="jump-world">Explore their world ↓</button></div></div></section><section class="artist-music" aria-labelledby="artist-music-title"><div class="artist-section-heading"><h2 id="artist-music-title">The music</h2><span class="muted">${a.releases.length} ${a.releases.length===1?'release':'releases'}</span></div>${a.releases.map(r=>`<article class="artist-release"><a href="#record/${r.id}" class="artist-release-link"><img src="${asset(r)}" alt="${escapeArtist(r.title)} cover" width="112" height="112"><div><span class="eyebrow">${r.year} / ${r.catalog}</span><h3>${escapeArtist(r.title)}</h3><p>${trackCount(r)} ${trackUnit(r).toLowerCase()} · ${fmt(sideDuration(r,0)+sideDuration(r,1))}</p></div><span aria-hidden="true">↗</span></a>${saveButton(r)}</article>`).join('')}</section><section class="artist-world" aria-labelledby="artist-world-title"><div class="artist-section-heading"><div><p class="eyebrow red">OFF THE RECORD</p><h2 id="artist-world-title" tabindex="-1">Their world</h2><p class="artist-world-intro">Works in progress. Moments worth keeping. A little closer.</p></div><span class="world-view-label">▦ Grid view</span></div><div class="filters world-filters" role="group" aria-label="Filter artist journal">${['All',...new Set(a.items.map(x=>x.category))].map(c=>`<button class="filter ${worldCategory===c?'active':''}" data-action="world-filter" data-category="${c}" data-artist="${a.id}" aria-pressed="${worldCategory===c}">${c==='All'?'Everything':c}</button>`).join('')}</div><div id="artist-world-grid">${worldGrid(a)}</div><p class="legal-note">Fictional journal. Images and notes are illustrative demo material.</p></section><section class="artist-more"><div class="artist-section-heading"><h2>Another world to step into</h2><a class="back" href="#artists">All artists ↗</a></div>${artistRail(allArtists().filter(x=>x.id!==id),'More artists')}</section>`;
}
function openWorldItem(artistId,itemId){
 const a=allArtists().find(x=>x.id===artistId),item=a?.items.find(x=>x.id===itemId);if(!item)return;
 const content=`<article class="world-detail"><p class="eyebrow red">${escapeArtist(a.name)} / ${item.category}</p><h2 id="world-dialog-title">${escapeArtist(item.title)}</h2>${item.type==='image'?`<img src="${item.src}" alt="${escapeArtist(item.alt)}"><p>${escapeArtist(item.caption)}</p>`:`<blockquote>${escapeArtist(item.body)}</blockquote><p>${escapeArtist(a.name)}</p>`}${item.recordId?`<a class="secondary" href="#record/${item.recordId}" data-action="world-record">Explore the record ↗</a>`:''}<p class="legal-note">Fictional journal / illustrative demo material.</p></article>`;
 modal(content);$('#dialog').classList.add('world-dialog');$('#dialog').setAttribute('aria-labelledby','world-dialog-title');
}
function resetWorldDialog(){$('#dialog').classList.remove('world-dialog');$('#dialog').removeAttribute('aria-labelledby')}
function bindArtistEvents(){
 $('#dialog').addEventListener('close',resetWorldDialog);
 document.addEventListener('input',e=>{if(e.target.id==='artist-search'){artistQuery=e.target.value;$('#artist-results').innerHTML=artistDirectoryResults()}});
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;
  const action=b.dataset.action;
  if(action==='artist-genre'){artistGenre=b.dataset.genre;$('#artist-results').innerHTML=artistDirectoryResults();document.querySelectorAll('[data-action="artist-genre"]').forEach(x=>{const active=x.dataset.genre===artistGenre;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))})}
  if(action==='clear-artists'){artistQuery='';artistGenre='All';main.innerHTML=artistsView();$('#artist-search').focus()}
  if(action==='world-filter'){worldCategory=b.dataset.category;const a=allArtists().find(x=>x.id===b.dataset.artist);if(a)$('#artist-world-grid').innerHTML=worldGrid(a);document.querySelectorAll('[data-action="world-filter"]').forEach(x=>{const active=x.dataset.category===worldCategory;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))})}
  if(action==='world-open')openWorldItem(b.dataset.artist,b.dataset.item);
  if(action==='world-record')$('#dialog').close();
  if(action==='artist-play'){const r=getRecord(b.dataset.id);if(current.id!==r.id){pause();current=r;side=0;track=0;source()}else if(!audio.getAttribute('src')||audio.ended){track=0;source()}resume()}
  if(action==='jump-world'){const title=$('#artist-world-title');title.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});title.focus({preventScroll:true})}
 });
}
